// The dates one edition works with. NBA games are dated in US Eastern time: at
// 8h in Brasília, "last night" is still yesterday over there. SEXTO_DATA
// (YYYY-MM-DD) replays any past morning, for tests and backfills.
function calcularDatas(agora) {
  const dia = (d, tz) =>
    new Intl.DateTimeFormat("en-CA", { timeZone: tz, year: "numeric", month: "2-digit", day: "2-digit" }).format(d);
  const ontem = new Date(agora.getTime() - 24 * 3600 * 1000);
  return {
    dataEdicao: dia(agora, "America/Sao_Paulo"),
    ontem: dia(ontem, "America/New_York").replaceAll("-", ""),
    hoje: dia(agora, "America/New_York").replaceAll("-", ""),
    // News window: a little over a day, so nothing published at 7:59 slips through.
    desde: new Date(agora.getTime() - 26 * 3600 * 1000).toISOString(),
  };
}

if (typeof $input !== "undefined") {
  const fixa = $env.SEXTO_DATA;
  const agora = fixa ? new Date(`${fixa}T08:00:00-03:00`) : new Date();
  return [{ json: calcularDatas(agora) }];
} else {
  module.exports = { calcularDatas };
}

// Last night's finished games from ESPN's scoreboard JSON.
function lerPlacares(resposta) {
  if (!resposta || resposta.error || !Array.isArray(resposta.events)) {
    return { tipo: "resultados", jogos: [], falha: "placares indisponíveis" };
  }
  const lider = (time, categoria) => {
    const l = time.leaders?.find((x) => x.name === categoria)?.leaders?.[0];
    return l ? { nome: l.athlete?.displayName, valor: Number(l.value) } : null;
  };
  const lado = (t) => ({
    sigla: t.team.abbreviation,
    nome: t.team.displayName,
    apelido: t.team.shortDisplayName,
    pontos: Number(t.score),
    campanha: t.records?.[0]?.summary ?? null,
    venceu: Boolean(t.winner),
    cestinha: lider(t, "points"),
    rebotes: lider(t, "rebounds"),
    assistencias: lider(t, "assists"),
  });
  const jogos = resposta.events
    .filter((e) => e.status?.type?.completed)
    .map((e) => {
      const c = e.competitions[0];
      const casa = lado(c.competitors.find((t) => t.homeAway === "home"));
      const visitante = lado(c.competitors.find((t) => t.homeAway === "away"));
      return {
        id: String(e.id),
        casa,
        visitante,
        prorrogacoes: Math.max(0, (e.status.period ?? 4) - 4),
        manchete: c.headlines?.[0]?.description ?? null,
      };
    });
  return { tipo: "resultados", jogos, falha: null };
}

if (typeof $input !== "undefined") {
  return [{ json: lerPlacares($input.first().json) }];
} else {
  module.exports = { lerPlacares };
}

// Tonight's games, with the tip-off in Brasília time.
function lerAgenda(resposta) {
  if (!resposta || resposta.error || !Array.isArray(resposta.events)) {
    return { tipo: "agenda", jogos: [], falha: "agenda indisponível" };
  }
  const hora = (iso) =>
    new Intl.DateTimeFormat("pt-BR", { timeZone: "America/Sao_Paulo", hour: "2-digit", minute: "2-digit" }).format(new Date(iso));
  const lado = (t) => ({ sigla: t.team.abbreviation, nome: t.team.displayName, apelido: t.team.shortDisplayName, campanha: t.records?.[0]?.summary ?? null });
  const jogos = resposta.events
    .filter((e) => e.status?.type?.state === "pre")
    .sort((a, b) => a.date.localeCompare(b.date))
    .map((e) => {
      const c = e.competitions[0];
      return {
        id: String(e.id),
        hora: hora(e.date),
        casa: lado(c.competitors.find((t) => t.homeAway === "home")),
        visitante: lado(c.competitors.find((t) => t.homeAway === "away")),
      };
    });
  return { tipo: "agenda", jogos, falha: null };
}

if (typeof $input !== "undefined") {
  return [{ json: lerAgenda($input.first().json) }];
} else {
  module.exports = { lerAgenda };
}

// Joins the news sources into one list: RSS feeds (one n8n item per story) and
// Lance's news sitemap (one item holding the whole XML). ESPN Brasil's "NBA" feed
// and Lance's sitemap mix in every sport, so only URLs under /nba/ count there.
const FONTES = [
  ["espn.com.br", "espn_br"],
  ["lance.com.br", "lance"],
  ["espn.com", "espn"],
];
const MISTURADAS = new Set(["espn_br", "lance"]);

function juntarNoticias(entradas, desde) {
  const fonteDe = (url) => FONTES.find(([trecho]) => url.includes(trecho))?.[1] ?? "outra";
  const limite = new Date(desde).getTime();
  const lista = [];
  for (const j of entradas) {
    if (j.urlset) {
      for (const u of [].concat(j.urlset.url ?? [])) {
        const loc = String(u.loc ?? "");
        if (!loc.includes("/nba/")) continue; // the sitemap covers every sport
        const n = u["news:news"] ?? {};
        lista.push({ titulo: n["news:title"], url: loc, publicada_em: n["news:publication_date"], resumo: "" });
      }
    } else if (j.link && j.title) {
      lista.push({
        titulo: j.title,
        url: j.link,
        publicada_em: j.isoDate ?? j.pubDate,
        resumo: String(j.contentSnippet ?? "").replace(/\s+/g, " ").trim().slice(0, 400),
      });
    }
  }
  const vistas = new Set();
  return lista
    .filter((n) => n.titulo && n.url && n.publicada_em && new Date(n.publicada_em).getTime() >= limite)
    .filter((n) => !vistas.has(n.url) && vistas.add(n.url))
    .map((n) => ({ ...n, fonte: fonteDe(n.url), titulo: String(n.titulo).trim() }))
    .filter((n) => !MISTURADAS.has(n.fonte) || n.url.includes("/nba/"))
    .sort((a, b) => new Date(b.publicada_em) - new Date(a.publicada_em))
    .slice(0, 40);
}

if (typeof $input !== "undefined") {
  const entradas = $input.all().map((i) => i.json).filter((j) => !j.error);
  return [{ json: { noticias: juntarNoticias(entradas, $("Datas").first().json.desde) } }];
} else {
  module.exports = { juntarNoticias };
}

// Postgres returned only the stories it had never seen (ON CONFLICT on the URL);
// put their summaries back for the model.
const novas = $input.first().json.novas ?? [];
const coletadas = new Map($("Notícias das últimas 24h").first().json.noticias.map((n) => [n.url, n]));
return [{ json: { tipo: "noticias", noticias: novas.map((n) => ({ id: n.id, ...coletadas.get(n.url) })) } }];

// The official injury report is a PDF published every 15 minutes on the NBA's
// file server, the time in its name ("Injury-Report_2026-10-21_09_45AM.pdf").
// The page that lists them blocks bots, so instead of scraping it this walks back
// from now in 15-minute steps and takes the first file that exists. The files
// are public; this bot still says who it is.
function candidatos(agora) {
  const partes = Object.fromEntries(
    new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hour12: false })
      .formatToParts(agora)
      .map((p) => [p.type, p.value]),
  );
  const dia = `${partes.year}-${partes.month}-${partes.day}`;
  let minutos = (Number(partes.hour) % 24) * 60 + Math.floor(Number(partes.minute) / 15) * 15;
  const lista = [];
  for (; minutos >= 0 && lista.length < 40; minutos -= 15) {
    const h24 = Math.floor(minutos / 60);
    const h12 = String(h24 % 12 || 12).padStart(2, "0");
    const m = String(minutos % 60).padStart(2, "0");
    lista.push(`https://ak-static.cms.nba.com/referee/injury/Injury-Report_${dia}_${h12}_${m}${h24 < 12 ? "AM" : "PM"}.pdf`);
  }
  return lista;
}

if (typeof $input !== "undefined") {
  const fixa = $env.SEXTO_DATA;
  const agora = fixa ? new Date(`${fixa}T08:00:00-03:00`) : new Date();
  for (const url of candidatos(agora)) {
    try {
      await this.helpers.httpRequest({ method: "HEAD", url, headers: { "User-Agent": "Mozilla/5.0 (compatible; SextoHomem/1.0; +https://github.com/guialmm/sexto-homem)" } });
      return [{ json: { pdf: url } }];
    } catch {
      // not published at that time: try 15 minutes earlier
    }
  }
  return [{ json: { pdf: null } }];
} else {
  module.exports = { candidatos };
}

// Turns the official NBA injury report (a PDF whose text comes out one word per
// line) into { sigla: [{ jogador, status, motivo }] } for today's games.
//
// The PDF has no structure to rely on, only patterns: a matchup "ATL@ORL", a
// team's full name, then players as "Last, First" followed by a status word.
// Everything between one player's status and the next player is the reason,
// minus the page header the PDF repeats when a list crosses a page break.

const TIMES = {
  'Atlanta Hawks': 'ATL', 'Boston Celtics': 'BOS', 'Brooklyn Nets': 'BKN', 'Charlotte Hornets': 'CHA',
  'Chicago Bulls': 'CHI', 'Cleveland Cavaliers': 'CLE', 'Dallas Mavericks': 'DAL', 'Denver Nuggets': 'DEN',
  'Detroit Pistons': 'DET', 'Golden State Warriors': 'GS', 'Houston Rockets': 'HOU', 'Indiana Pacers': 'IND',
  'LA Clippers': 'LAC', 'Los Angeles Lakers': 'LAL', 'Memphis Grizzlies': 'MEM', 'Miami Heat': 'MIA',
  'Milwaukee Bucks': 'MIL', 'Minnesota Timberwolves': 'MIN', 'New Orleans Pelicans': 'NO', 'New York Knicks': 'NY',
  'Oklahoma City Thunder': 'OKC', 'Orlando Magic': 'ORL', 'Philadelphia 76ers': 'PHI', 'Phoenix Suns': 'PHX',
  'Portland Trail Blazers': 'POR', 'Sacramento Kings': 'SAC', 'San Antonio Spurs': 'SA', 'Toronto Raptors': 'TOR',
  'Utah Jazz': 'UTAH', 'Washington Wizards': 'WSH',
};
const STATUS = { Out: 'fora', Doubtful: 'dúvida', Questionable: 'questionável', Probable: 'provável', Available: 'disponível' };
// Players on two-way contracts assigned to the G League are not news.
const IGNORAR = /G League|Two-?\s?Way/i;

function lerRelatorio(textoBruto) {
  // Rejoin words the PDF split ("Two- Way", "Gilgeous- Alexander") and flatten lines.
  const texto = String(textoBruto ?? '').replace(/-\s+(?=\w)/g, '-').replace(/\s+/g, ' ');
  const nomes = Object.keys(TIMES).map((n) => n.replace(/\s+/g, '\\s+')).join('|');
  const marcos = [];
  for (const m of texto.matchAll(new RegExp(`\\b(${nomes})\\b`, 'g'))) {
    marcos.push({ pos: m.index, sigla: TIMES[m[1].replace(/\s+/g, ' ')] });
  }
  const jogador = /\b([A-Z][A-Za-z'.-]+(?: (?:Jr\.|Sr\.|II|III|IV))?), ([A-Z][A-Za-z'.-]+(?: [A-Z][A-Za-z'.-]+)?) (Out|Doubtful|Questionable|Probable|Available)\b/g;
  const achados = [...texto.matchAll(jogador)];
  const porTime = {};
  achados.forEach((m, i) => {
    const time = [...marcos].reverse().find((t) => t.pos < m.index);
    if (!time) return;
    const fimMotivo = Math.min(
      achados[i + 1]?.index ?? texto.length,
      ...marcos.filter((t) => t.pos > m.index).map((t) => t.pos).slice(0, 1),
      ...[...texto.slice(m.index).matchAll(/\b[A-Z]{2,4}@[A-Z]{2,4}\b|\d{2}:\d{2} \(ET\)|Page \d+ of \d+|Injury Report:|Game Date/g)].slice(0, 1).map((x) => m.index + x.index),
    );
    const motivo = texto.slice(m.index + m[0].length, fimMotivo).trim().replace(/^Injury\/Illness ?- ?/, '');
    if (IGNORAR.test(motivo)) return;
    (porTime[time.sigla] ??= []).push({ jogador: `${m[2]} ${m[1]}`, status: STATUS[m[3]], motivo });
  });
  return porTime;
}

// In n8n this file is the body of a Code node; under Node it is a module for the tests.
if (typeof $input !== 'undefined') {
  const entrada = $input.first().json;
  return [{ json: { tipo: 'desfalques', porTime: entrada.text ? lerRelatorio(entrada.text) : {}, falha: entrada.text ? null : 'relatório de lesões indisponível' } }];
} else {
  module.exports = { lerRelatorio };
}

// Builds the request for the model. It writes the prose; it never decides facts:
// scores, links and injuries come from the sources, and the model refers to
// games and stories only by the ids it was given.
const SISTEMA = `Você escreve o Sexto Homem, newsletter diária da NBA em português do Brasil,
lida às 8h por quem dormiu antes dos jogos acabarem.
Tom: fã que entende de basquete, direto, com bom humor leve. Nada de clichê de IA,
nada de emoji, nada de exclamação em toda frase.
Regras:
- Use somente os dados fornecidos. Não invente placares, números, lesões nem fatos.
- Refira-se a jogos e notícias apenas pelos "id" recebidos.
- Escolha no máximo 6 notícias, as mais relevantes, sem repetir assunto; ignore as que
  não forem sobre a NBA. Reescreva o título em português e resuma em uma ou duas frases.
- Para cada jogo de ontem, uma frase de comentário com o que decidiu o jogo.
- Traduza TODOS os motivos de lesão da lista para um português curto e natural.
- Para cada jogo de hoje, escolha até 2 desfalques que mais pesam (titulares e estrelas),
  usando exatamente os nomes da lista; se nenhum pesa, não escolha nenhum.`;

const ESQUEMA = {
  type: "object",
  properties: {
    assunto: { type: "string", description: "Assunto do e-mail, até 70 caracteres, sobre o fato mais marcante" },
    abertura: { type: "string", description: "Duas ou três frases abrindo a edição" },
    jogos: { type: "array", items: { type: "object", properties: { id: { type: "string" }, comentario: { type: "string" } }, required: ["id", "comentario"] } },
    noticias: {
      type: "array",
      items: { type: "object", properties: { id: { type: "integer" }, titulo: { type: "string" }, resumo: { type: "string" } }, required: ["id", "titulo", "resumo"] },
    },
    motivos: { type: "array", items: { type: "object", properties: { original: { type: "string" }, traducao: { type: "string" } }, required: ["original", "traducao"] } },
    desfalques_importantes: { type: "array", items: { type: "string" }, description: "Nomes, exatamente como na lista" },
  },
  required: ["assunto", "abertura", "jogos", "noticias", "motivos", "desfalques_importantes"],
};

function montarPedido({ resultados, agenda, noticias, desfalques }) {
  const placar = (j) => `${j.visitante.apelido} ${j.visitante.pontos} x ${j.casa.pontos} ${j.casa.apelido}`;
  const timesDeHoje = new Set(agenda.jogos.flatMap((j) => [j.casa.sigla, j.visitante.sigla]));
  const relevantes = Object.entries(desfalques.porTime ?? {})
    .filter(([sigla]) => timesDeHoje.has(sigla))
    .flatMap(([, lista]) => lista.filter((d) => d.status === "fora" || d.status === "dúvida"));
  const dados = {
    jogos_de_ontem: resultados.jogos.map((j) => ({
      id: j.id,
      placar: placar(j),
      prorrogacoes: j.prorrogacoes,
      manchete_em_ingles: j.manchete,
      destaques: [j.visitante, j.casa].map((t) => ({ time: t.apelido, cestinha: t.cestinha, rebotes: t.rebotes, assistencias: t.assistencias })),
    })),
    noticias: noticias.noticias.map((n) => ({ id: n.id, fonte: n.fonte, titulo: n.titulo, resumo: n.resumo })),
    jogos_de_hoje: agenda.jogos.map((j) => ({
      jogo: `${j.hora} ${j.visitante.apelido} x ${j.casa.apelido}`,
      desfalques: [j.visitante.sigla, j.casa.sigla].flatMap((sigla) =>
        (desfalques.porTime?.[sigla] ?? []).filter((d) => d.status === "fora" || d.status === "dúvida").map((d) => d.jogador),
      ),
    })),
    motivos_de_lesao: [...new Set(relevantes.map((d) => d.motivo))],
  };
  return {
    systemInstruction: { parts: [{ text: SISTEMA }] },
    contents: [{ role: "user", parts: [{ text: JSON.stringify(dados) }] }],
    generationConfig: { temperature: 0.6, responseMimeType: "application/json", responseSchema: ESQUEMA },
  };
}

if (typeof $input !== "undefined") {
  const pegar = (tipo) => $input.all().map((i) => i.json).find((j) => j.tipo === tipo) ?? { jogos: [], noticias: [], porTime: {} };
  const partes = { resultados: pegar("resultados"), agenda: pegar("agenda"), noticias: pegar("noticias"), desfalques: pegar("desfalques") };
  return [{ json: { ...partes, requisicao: montarPedido(partes) } }];
} else {
  module.exports = { montarPedido, ESQUEMA };
}

// Asks Gemini for the edition's prose. The free tier is generous but bursty:
// a model may answer 503 at peak hours, and each one allows ~20 requests a day.
// So: try the models in order, wait and retry overloaded ones, skip a model whose
// daily quota is gone. If all fail, pass the error on: the edition goes out
// without commentary rather than not at all.
const MODELOS = ["gemini-3.6-flash", "gemini-3.5-flash", "gemini-3-flash-preview", "gemini-flash-lite-latest"];
const espera = (ms) => new Promise((r) => setTimeout(r, ms));

const pedido = $input.first().json.requisicao;
const tentativas = [];
for (let rodada = 0; rodada < 3; rodada++) {
  for (const modelo of MODELOS) {
    if (tentativas.some((t) => t.modelo === modelo && t.semCota)) continue;
    try {
      const resposta = await this.helpers.httpRequest({
        method: "POST",
        url: `https://generativelanguage.googleapis.com/v1beta/models/${modelo}:generateContent`,
        headers: { "x-goog-api-key": $env.GEMINI_API_KEY },
        body: pedido,
        json: true,
        timeout: 90000,
      });
      return [{ json: { ...resposta, modelo, tentativas } }];
    } catch (erro) {
      const status = erro.httpCode ?? erro.response?.status ?? erro.status;
      const texto = JSON.stringify(erro.response?.data ?? erro.message ?? "");
      tentativas.push({ modelo, status, semCota: status == 429 && texto.includes("PerDay") });
    }
  }
  await espera(15000 * (rodada + 1));
}
return [{ json: { error: { message: "todos os modelos do Gemini falharam" }, tentativas } }];

// Turns the sources plus the model's prose into the e-mail. Links and scores
// always come from the sources; any id the model invents is dropped, and if the
// model failed altogether the edition still goes out, just without commentary.

const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const NOME_FONTE = { espn_br: "ESPN Brasil", lance: "Lance!", espn: "ESPN" };
const COR = { tinta: "#14110f", apagado: "#7a7068", linha: "#ece6df", laranja: "#e8572a", fundo: "#faf7f3" };

function lerIA(resposta) {
  try {
    const texto = resposta?.candidates?.[0]?.content?.parts?.[0]?.text;
    return texto ? JSON.parse(texto) : null;
  } catch {
    return null;
  }
}

function dataPorExtenso(iso) {
  return new Intl.DateTimeFormat("pt-BR", { weekday: "long", day: "numeric", month: "long", timeZone: "UTC" }).format(new Date(`${iso}T12:00:00Z`));
}

function secao(titulo, corpo) {
  return `<h2 style="font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:${COR.apagado};margin:36px 0 12px;border-top:1px solid ${COR.linha};padding-top:20px">${titulo}</h2>${corpo}`;
}

function montarEdicao({ dataEdicao, resultados, agenda, noticias, desfalques }, ia) {
  const idsJogos = new Set(resultados.jogos.map((j) => j.id));
  const porId = new Map(noticias.noticias.map((n) => [n.id, n]));
  const comentarios = new Map((ia?.jogos ?? []).filter((j) => idsJogos.has(j.id)).map((j) => [j.id, j.comentario]));
  const escolhidas = (ia?.noticias ?? []).filter((n) => porId.has(n.id)).slice(0, 6);
  // Without the model: the newest stories in Portuguese, titles as published.
  const lista = escolhidas.length
    ? escolhidas.map((n) => ({ ...porId.get(n.id), titulo: n.titulo, resumo: n.resumo }))
    : noticias.noticias.filter((n) => n.fonte !== "espn").slice(0, 6).map((n) => ({ ...n, resumo: "" }));
  const traducao = new Map((ia?.motivos ?? []).map((m) => [m.original, m.traducao]));
  // Only names that are really in the report: anything else the model wrote is ignored.
  const importantes = new Set(ia?.desfalques_importantes ?? []);

  if (!resultados.jogos.length && !lista.length) return null; // nothing happened: no edition

  const jogosHtml = resultados.jogos
    .map((j) => {
      const time = (t) => `<span style="font-weight:${t.venceu ? 700 : 400};color:${t.venceu ? COR.tinta : COR.apagado}">${esc(t.apelido)} ${t.pontos}</span>`;
      const ot = j.prorrogacoes ? ` <span style="color:${COR.apagado};font-size:13px">(${j.prorrogacoes > 1 ? `${j.prorrogacoes} prorrogações` : "prorrogação"})</span>` : "";
      const cestinhas = [j.visitante, j.casa]
        .filter((t) => t.cestinha)
        .map((t) => `${esc(t.cestinha.nome)} ${t.cestinha.valor} pts`)
        .join(" · ");
      const comentario = comentarios.get(j.id);
      return `<div style="margin:0 0 18px">
  <p style="margin:0;font-size:18px">${time(j.visitante)} <span style="color:${COR.apagado}">x</span> ${time(j.casa)}${ot}</p>
  <p style="margin:4px 0 0;font-size:13px;color:${COR.apagado}">Cestinhas: ${cestinhas}</p>
  ${comentario ? `<p style="margin:6px 0 0;font-size:15px;line-height:1.55">${esc(comentario)}</p>` : ""}
</div>`;
    })
    .join("");

  const noticiasHtml = lista
    .map(
      (n) => `<div style="margin:0 0 18px">
  <a href="${esc(n.url)}" style="font-size:16px;font-weight:700;color:${COR.tinta};text-decoration:none">${esc(n.titulo)}</a>
  ${n.resumo ? `<p style="margin:4px 0 0;font-size:15px;line-height:1.55">${esc(n.resumo)}</p>` : ""}
  <p style="margin:4px 0 0;font-size:12px;color:${COR.apagado}">${esc(NOME_FONTE[n.fonte] ?? n.fonte)} · <a href="${esc(n.url)}" style="color:${COR.laranja}">ler</a></p>
</div>`,
    )
    .join("");

  const fora = (sigla) =>
    (desfalques.porTime?.[sigla] ?? [])
      .filter((d) => d.status === "fora" || d.status === "dúvida")
      .map((d) => ({ nome: d.jogador, texto: `${esc(d.jogador)}${d.status === "dúvida" ? " (dúvida)" : ""}, ${esc(traducao.get(d.motivo) ?? d.motivo)}` }));
  // A long list of season-long injuries is noise: show the (at most) two absences
  // that matter, as picked by the model from the report, and count the rest.
  const agendaHtml = agenda.jogos
    .map((j) => {
      const todas = [...fora(j.visitante.sigla), ...fora(j.casa.sigla)];
      const escolhidas = ia ? todas.filter((b) => importantes.has(b.nome)) : todas.slice(0, 2);
      const resto = todas.length - escolhidas.length;
      const linha = [escolhidas.map((b) => b.texto).join("; "), resto ? `${escolhidas.length ? "e mais " : ""}${resto} fora` : ""]
        .filter(Boolean)
        .join("; ");
      return `<div style="margin:0 0 14px">
  <p style="margin:0;font-size:16px"><span style="font-family:monospace;color:${COR.laranja}">${esc(j.hora)}</span>&nbsp; ${esc(j.visitante.apelido)} x ${esc(j.casa.apelido)}</p>
  ${linha ? `<p style="margin:3px 0 0;font-size:13px;color:${COR.apagado}">Desfalques: ${linha}</p>` : ""}
</div>`;
    })
    .join("");

  const avisos = [resultados.falha, agenda.falha, desfalques.falha].filter(Boolean);
  const assunto = (ia?.assunto ?? `O que rolou na NBA: ${dataPorExtenso(dataEdicao)}`).slice(0, 90);
  const html = `<div style="background:${COR.fundo};padding:24px 0"><div style="font-family:Helvetica,Arial,sans-serif;max-width:600px;margin:0 auto;padding:32px 28px;background:#fff;color:${COR.tinta}">
<p style="margin:0;font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:${COR.laranja};font-weight:700">Sexto Homem</p>
<p style="margin:4px 0 0;font-size:13px;color:${COR.apagado}">${esc(dataPorExtenso(dataEdicao))}</p>
<p style="margin:22px 0 0;font-size:17px;line-height:1.6">Bom dia, {{NOME}}. ${esc(ia?.abertura ?? "Aqui está o que rolou na NBA enquanto você dormia.")}</p>
{{DESTAQUE_TIME}}
${resultados.jogos.length ? secao("Resultados da noite", jogosHtml) : ""}
${lista.length ? secao("O que rolou", noticiasHtml) : ""}
${agenda.jogos.length ? secao("Hoje à noite", agendaHtml) : ""}
${avisos.length ? `<p style="margin:24px 0 0;font-size:12px;color:${COR.apagado}">Hoje faltou: ${esc(avisos.join(", "))}.</p>` : ""}
<p style="margin:36px 0 0;font-size:12px;line-height:1.6;color:${COR.apagado};border-top:1px solid ${COR.linha};padding-top:16px">Você recebe o Sexto Homem porque se inscreveu e confirmou seu e-mail. Placares e estatísticas: ESPN. Desfalques: relatório oficial da NBA. <a href="{{DESCADASTRAR}}" style="color:${COR.apagado}">Descadastrar em um clique</a>.</p>
</div></div>`;

  return { dataEdicao, assunto, html, jogos: resultados.jogos.length, noticiasIds: lista.map((n) => n.id).filter(Number.isInteger), comIA: Boolean(ia), resultados, agenda };
}

if (typeof $input !== "undefined") {
  const base = $("Preparar pedido à IA").first().json;
  const edicao = montarEdicao({ ...base, dataEdicao: $("Datas").first().json.dataEdicao }, lerIA($input.first().json));
  return edicao ? [{ json: edicao }] : [];
} else {
  module.exports = { montarEdicao, lerIA };
}

// One e-mail per subscriber: first name, their unsubscribe link, and a line
// about their team when it played last night or plays tonight.
function personalizar(edicao, inscrito, siteUrl) {
  const time = inscrito.time_favorito;
  let destaque = "";
  const jogo = edicao.resultados.jogos.find((j) => j.casa.sigla === time || j.visitante.sigla === time);
  const hoje = edicao.agenda.jogos.find((j) => j.casa.sigla === time || j.visitante.sigla === time);
  if (jogo) {
    const meu = jogo.casa.sigla === time ? jogo.casa : jogo.visitante;
    const outro = meu === jogo.casa ? jogo.visitante : jogo.casa;
    // Team names are English plurals ("Celtics", "Pistons"): no Portuguese article fits
    // every one of them, so the sentence is built without articles.
    const quem = meu.cestinha ? ` ${meu.cestinha.nome} fez ${meu.cestinha.valor}.` : "";
    destaque = `Seu time ${meu.venceu ? "venceu" : "perdeu"}: ${meu.apelido} ${meu.pontos} x ${outro.pontos} ${outro.apelido}.${quem}`;
  } else if (hoje) {
    const outro = hoje.casa.sigla === time ? hoje.visitante : hoje.casa;
    const meu = hoje.casa.sigla === time ? hoje.casa : hoje.visitante;
    destaque = `Seu time joga hoje: ${meu.apelido} x ${outro.apelido}, às ${hoje.hora}.`;
  }
  const bloco = destaque
    ? `<p style="margin:18px 0 0;padding:12px 16px;background:#fdf1ec;border-left:3px solid #e8572a;font-size:15px">${destaque.replace(/[<>&]/g, "")}</p>`
    : "";
  const primeiroNome = String(inscrito.nome).trim().split(/\s+/)[0].replace(/[<>&"]/g, "");
  return {
    para: inscrito.email,
    assunto: edicao.assunto,
    html: edicao.html
      .replace("{{NOME}}", primeiroNome)
      .replace("{{DESTAQUE_TIME}}", bloco)
      .replace("{{DESCADASTRAR}}", `${siteUrl}/descadastrar?token=${inscrito.token_descadastro}`),
  };
}

if (typeof $input !== "undefined") {
  const edicao = $("Montar edição").first().json;
  return $input.all().map((i) => ({ json: { ...i.json, ...personalizar(edicao, i.json, $env.SITE_URL) } }));
} else {
  module.exports = { personalizar };
}
